const cfg = {
  enabled: true,   // công tắc tắt khẩn cấp

  // Origin = giao thức + domain (KHÔNG có đường dẫn). Mọi trang dưới domain này đều được cấp token & gọi AI.
  // >>> SỬA: thay <TEN-GITHUB> bằng tên tài khoản GitHub chứa bản clone (vd. 'https://nguyenvana.github.io').
