  // Domain n8n của hosting: proxy ghi đè header Origin thành giá trị này (xem Token Parse / Chat Gate)
  proxyOrigins: ['http://n8nhosting-67079049.phoaify.com', 'https://n8nhosting-67079049.phoaify.com'],

  // apiKey Web công khai của Firebase project "popaiclone" (js/firebase-config.js) — chỉ để xác minh học sinh đã đăng nhập
  firebaseApiKey: 'AIzaSyBA3bU_SdVNTHl73Vtfcj_eB3R9bEQrbls',

  // Khoá xem log/thống kê qua endpoint /popaiclone-gw-admin. Để rỗng = tắt endpoint. Nên ≥ 16 ký tự ngẫu nhiên.
  adminKey: '',

  // Chặn riêng một web con (dạng "domain/thư-mục-đầu-tiên")
  blockedSites: [],

  tokenTtlSec: 300,          // tuổi thọ token (60–900)
  tokenIssuePerHour: 40,     // số token tối đa/người dùng/web/giờ
  perUserPerMin: 6,          // số câu hỏi/người dùng/phút
