  maxHistory: 12,
  maxContextLen: 4000,
  models: ['gpt-5-mini', 'gpt-4o-mini', 'gpt-4.1-mini-2025-04-14'],  // thử lần lượt khi model trước lỗi 5xx
  systemPrompt: '',          // để rỗng = dùng prompt POP-AI mặc định trong node "PC Chat Gate"

  logKeep: 300,              // số dòng log gần nhất giữ lại trong n8n

  maxTaskLen: 15000,
  anonPerIpPerDay: 300,

  // Không có hồ sơ riêng: mọi web gọi vào đều dùng cấu hình mặc định (bắt buộc đăng nhập Firebase + prompt POP-AI).
  profiles: {}
};
